public class ExceptionIntroductionDemo {
    public static void divide(int a, int b) {
        System.out.println("Attempting division: " + a + " / " + b);
        int quotient = a / b; // Throws ArithmeticException if b == 0
        System.out.println("Division successful! Result: " + quotient);
    }

    public static void main(String[] args) {
        System.out.println("--- Scenario 1: Normal Flow ---");
        divide(100, 5); // Executes cleanly

        System.out.println("\n--- Scenario 2: Exceptional Flow ---");
        // Dividing by zero causes runtime ArithmeticException
        try {
            divide(100, 0);
        } catch (ArithmeticException e) {
            System.out.println("Emergency Handler: Cannot divide by zero!");
            System.out.println("Exception message: " + e.getMessage());
        }

        System.out.println("\nProgram resumed safely after handling exception!");
    }
}

