public class ArrayBoundsCatch {
    public static void main(String[] args) {
        int[] scores = {90, 85, 95};
        try {
            int score = scores[5];
            System.out.println("Score: " + score);
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("Handled Array Index Error: Index 5 out of bounds");
        }
    }
}

